// D-02: least-loaded round robin. Swap the sort for language / area / tier
// routing by editing ROUTE below - nothing else in the flow changes.
const lead = $('Assign Trigger').first().json;
const agents = $('Agent Workload').all().map(a => a.json)
                 .filter(a => a.role === 'Agent');
if (!agents.length) throw new Error('No active user with role Agent - nobody to assign to.');

const ROUTE = (list, lead) => list.sort((a, b) => a.open_leads - b.open_leads);
const chosen = ROUTE(agents, lead)[0];

const PORTAL = $('Config').first().json.portal_url;
const url = `${PORTAL}/record/SAL-001/${lead.id}`;
return [{ json: {
  lead_id: lead.id, doc_no: lead.doc_no,
  client_name: lead.client_name, contact: lead.contact,
  source: lead.source, property_interest: lead.property_interest,
  agent_name: chosen.full_name, agent_email: chosen.email,
  agent_open_leads: chosen.open_leads, record_url: url,
}}];

const p = $('Pick Agent').first().json;
const r = $json;
return [{ json: {
  channel: 'email,whatsapp,slack',
  to_email: p.agent_email,
  to_phone: '',
  slack_channel: 'dharani-leads',
  subject: `[NEW LEAD] ${p.client_name} - respond within ${$('Config').first().json.sla_minutes} minutes`,
  message:
`A new lead has just been assigned to you.

Client   : ${p.client_name}
Phone    : ${p.contact || '-'}
Source   : ${p.source}
Interest : ${p.property_interest || '-'}
Record   : ${r.doc_no}

Open it: ${p.record_url}

Log a call, a follow-up or a viewing against this client inside
${$('Config').first().json.sla_minutes} minutes. If nothing is logged, the lead
returns to the pool and your manager is told.`,
  _lead_id: r.id, _doc_no: r.doc_no, _client: p.client_name,
  _agent: p.agent_name, _assigned_at: r.updated_at,
}}];

const b = $('Brief The Agent').first().json;
const cfg = $('Config').first().json;
return [{ json: {
  channel: 'email,slack',
  to_email: cfg.sales_manager_email,
  slack_channel: 'dharani-leads',
  subject: `[SLA MISSED] ${b._client} - no contact logged by ${b._agent}`,
  message:
`${b._agent} was given lead ${b._doc_no} (${b._client}) and logged nothing
within ${cfg.sla_minutes} minutes.

The lead has been returned to the pool and is unassigned. Reassign it, or
let the next capture pick it up.

Record: ${cfg.portal_url}/record/SAL-001/${b._lead_id}

This miss is recorded against ${b._agent} in the record's notes and in the
portal's audit trail.`,
  _lead_id: b._lead_id, _agent: b._agent,
}}];
